import java.sql.*;import java.util.*;
public final class TaxSlabStore {public record Slab(String name,double from,double to,double rate){}private static final List<Slab> DEFAULTS=List.of(new Slab("Up to 3 Lakh",0,300000,0),new Slab("3 Lakh to 7 Lakh",300000,700000,5),new Slab("7 Lakh to 10 Lakh",700000,1000000,10),new Slab("10 Lakh to 12 Lakh",1000000,1200000,15),new Slab("12 Lakh to 15 Lakh",1200000,1500000,20),new Slab("Above 15 Lakh",1500000,Double.MAX_VALUE,30));static{migrate();}private TaxSlabStore(){}
 private static void migrate(){try(Connection c=DBConnection.getConnection();Statement s=c==null?null:c.createStatement()){if(s==null)return;try{s.executeUpdate("ALTER TABLE settings_tax_slabs ADD COLUMN slab_type TEXT DEFAULT 'TAX'");}catch(SQLException ignored){}try{s.executeUpdate("ALTER TABLE settings_tax_slabs ADD COLUMN is_deleted INTEGER NOT NULL DEFAULT 0");}catch(SQLException ignored){}try{s.executeUpdate("ALTER TABLE settings_tax_slabs ADD COLUMN deleted_at TEXT");}catch(SQLException ignored){}s.executeUpdate("UPDATE settings_tax_slabs SET slab_type='TAX' WHERE slab_type IS NULL OR slab_type='' ");}catch(SQLException ignored){}}
 public static synchronized List<Slab> list(){List<Slab> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c==null?null:c.prepareStatement("SELECT slab_name,from_amount,to_amount,tax_rate FROM settings_tax_slabs WHERE slab_type='TAX' AND is_deleted=0 ORDER BY slab_id")){if(p!=null){ResultSet r=p.executeQuery();while(r.next())out.add(new Slab(r.getString(1),r.getDouble(2),r.getDouble(3),r.getDouble(4)));}}catch(SQLException ignored){}return out.isEmpty()?new ArrayList<>(DEFAULTS):out;}
 public static synchronized void save(List<Slab> slabs)throws SQLException{if(slabs.isEmpty())throw new IllegalArgumentException("Add at least one tax slab.");try(Connection c=DBConnection.getConnection()){if(c==null)return;c.setAutoCommit(false);try(PreparedStatement hide=c.prepareStatement("UPDATE settings_tax_slabs SET is_deleted=1,deleted_at=CURRENT_TIMESTAMP WHERE slab_type='TAX' AND is_deleted=0");PreparedStatement revive=c.prepareStatement("UPDATE settings_tax_slabs SET from_amount=?,to_amount=?,tax_rate=?,is_deleted=0,deleted_at=NULL WHERE slab_name=? AND slab_type='TAX'");PreparedStatement add=c.prepareStatement("INSERT INTO settings_tax_slabs(slab_name,from_amount,to_amount,tax_rate,slab_type,is_deleted) VALUES(?,?,?,?, 'TAX',0)")){hide.executeUpdate();for(Slab s:slabs){if(s.name().isBlank()||s.from()<0||s.to()<s.from()||s.rate()<0)throw new IllegalArgumentException("Invalid tax slab");revive.setDouble(1,s.from());revive.setDouble(2,s.to());revive.setDouble(3,s.rate());revive.setString(4,s.name());if(revive.executeUpdate()==0){add.setString(1,s.name());add.setDouble(2,s.from());add.setDouble(3,s.to());add.setDouble(4,s.rate());add.executeUpdate();}}}c.commit();} }
 public static double monthlyTds(double monthlyWages){if(monthlyWages<=0)return 0;double taxable=Math.max(0,monthlyWages*12-PayrollRulesStore.standardDeduction());if(taxable<=PayrollRulesStore.rebate87aLimit())return 0;double tax=0;for(Slab s:list())tax+=Math.max(0,Math.min(taxable,s.to())-s.from())*s.rate()/100;return Money.round(tax*(1+PayrollRulesStore.cessRate()/100)/12);}
}
